package com.kaipai.controller.admin.ai;
import com.kaipai.common.result.R; import com.kaipai.model.ai.dto.*; import com.kaipai.service.ai.ProfileImportConfigService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/admin/ai/profile-import") @RequiredArgsConstructor public class AdminAiProfileImportController { private final ProfileImportConfigService service; @GetMapping("/config") @PreAuthorize("hasAuthority('page.system.ai-profile-import')") public R<ProfileImportCapabilityRespDTO> config(){return R.ok(service.capability());} @PutMapping("/config") @PreAuthorize("hasAuthority('action.system.ai-profile-import.update')") public R<ProfileImportConfigRespDTO> save(@RequestBody @Valid ProfileImportPublicConfigUpdateDTO dto){return R.ok(service.savePublicConfig(0L,dto));} @PutMapping("/secret") @PreAuthorize("hasAuthority('action.system.ai-profile-import.secret')") public R<ProfileImportConfigRespDTO> secret(@RequestBody ProfileImportSecretUpdateDTO dto){return R.ok(service.saveSecret(0L,dto));} @PutMapping("/enabled") @PreAuthorize("hasAuthority('action.system.ai-profile-import.update')") public R<ProfileImportConfigRespDTO> enabled(@RequestParam boolean value){return R.ok(service.setEnabled(0L,value));} @PostMapping("/test") @PreAuthorize("hasAuthority('action.system.ai-profile-import.test')") public R<ProfileImportConfigRespDTO> test(){return R.ok(service.testConnection(0L));} }
